// Define the mapping between Go types and Avro types.
var mapTypeToAvro = map[string]string{
	"int32": "int",
	"int64": "long",
	"uint32": "int",
	"uint64": "long",
	"float32": "double",
	"float64": "double",
	"string": "string",
}

func convertGoStructToFile(inputFile string) error {
	inputFilePath := inputFile + ".go"
	outputFilePath := inputFile + ".avsc"

	// Parse the input file using Go parser
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, inputFile+".go", nil, parser.ParseComments)
	if err != nil {
		return fmt.Errorf("failed to parse %s: %w", inputFile+".go", err)
	}

	// Get the name of the struct being parsed
	structName := file.Name.String()

	// Convert the struct to JSON
	jsonBytes, err := json.MarshalIndent(file.Type.Params[0].Value, "", "\t")
	if err != nil {
		return fmt.Errorf("failed to marshal struct: %w", err)
	}
	jsonString := string(jsonBytes)

	// Unmarshal the JSON into a map
	var structMap map[string]interface{}
	err = json.Unmarshal(jsonBytes, &structMap)
	if err != nil {
		return fmt.Errorf("failed to unmarshal JSON: %w", err)
	}

	// Generate the Avro schema
	schema := map[string]map[string]interface{}{"type": "record"}
	for fieldKey, fieldValue := range structMap {
		fieldType := mapTypeToAvro[fieldKey]
		schema["fields"] = append(schema["fields"].([]interface{}), map[string]interface{}{
			"name":  fieldKey,
			"type":  fieldType,
			"mode":  "required",
			"values": []interface{}{fieldType},
		})
	}
	schema["name"] = structName

	// Write the Avro schema to a file
	err = ioutil.WriteFile(outputFilePath, json.MarshalIndent(schema, "", "\t"))
	if err != nil {
		return fmt.Errorf("failed to write Avro schema: %w", err)
	}

	fmt.Printf("Generated Avro schema successfully at %s\n", outputFilePath)
	return nil
}

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run script.go <input_file_name> <output_file_name>")
		os.Exit(1)
	}

	inputFileName := os.Args[1]
	outputFileName := os.Args[2]

	if err := convertGoStructToFile(inputFileName); err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}
}
